import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../../context/AuthContext';

const Statistics = () => {
  const { token } = useContext(AuthContext);
  const [stats, setStats] = useState({
    totalRevenue: 0,
    totalOrders: 0,
    totalProducts: 0,
    totalUsers: 0,
    recentOrders: [],
    topProducts: [],
    topCustomers: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStatistics();
  }, []);

  const fetchStatistics = async () => {
    try {
      const config = {
        headers: {
          Authorization: `Bearer ${token}`
        }
      };

      // Fetch all data
      const [ordersRes, productsRes] = await Promise.all([
        axios.get('/api/orders/admin/all', config),
        axios.get('/api/products')
      ]);

      const orders = ordersRes.data.orders;
      const products = productsRes.data.products;

      // Calculate statistics
      const totalRevenue = orders.reduce((sum, order) => sum + order.totalPrice, 0);
      const recentOrders = orders.slice(0, 5);

      // Top products by revenue
      const productSales = {};
      orders.forEach(order => {
        order.items.forEach(item => {
          const id = item.product?._id || item.product;
          if (!productSales[id]) {
            productSales[id] = {
              name: item.name,
              quantity: 0,
              revenue: 0
            };
          }
          productSales[id].quantity += item.quantity;
          productSales[id].revenue += item.price * item.quantity;
        });
      });

      const topProducts = Object.values(productSales)
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 5);

      // Top customers by spending
      const customerSpending = {};
      orders.forEach(order => {
        const userId = order.user?._id;
        const userName = order.user?.name || 'Unknown User';
        if (!customerSpending[userId]) {
          customerSpending[userId] = {
            name: userName,
            totalSpent: 0,
            orderCount: 0
          };
        }
        customerSpending[userId].totalSpent += order.totalPrice;
        customerSpending[userId].orderCount += 1;
      });

      const topCustomers = Object.values(customerSpending)
        .sort((a, b) => b.totalSpent - a.totalSpent)
        .slice(0, 5);

      setStats({
        totalRevenue,
        totalOrders: orders.length,
        totalProducts: products.length,
        recentOrders,
        topProducts,
        topCustomers
      });
    } catch (error) {
      console.error('Error fetching statistics:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={styles.loading}>Loading statistics...</div>;
  }

  return (
    <div>
      {/* KPI Cards */}
      <div style={styles.kpiGrid}>
        <div style={styles.kpiCard}>
          <div style={styles.kpiIcon}>💰</div>
          <div>
            <div style={styles.kpiValue}>${stats.totalRevenue.toFixed(2)}</div>
            <div style={styles.kpiLabel}>Total Revenue</div>
          </div>
        </div>

        <div style={styles.kpiCard}>
          <div style={styles.kpiIcon}>📦</div>
          <div>
            <div style={styles.kpiValue}>{stats.totalOrders}</div>
            <div style={styles.kpiLabel}>Total Orders</div>
          </div>
        </div>

        <div style={styles.kpiCard}>
          <div style={styles.kpiIcon}>🛍️</div>
          <div>
            <div style={styles.kpiValue}>{stats.totalProducts}</div>
            <div style={styles.kpiLabel}>Total Products</div>
          </div>
        </div>
      </div>

      {/* Charts/Lists Section */}
      <div style={styles.grid}>
        {/* Top Products */}
        <div style={styles.card}>
          <h3 style={styles.cardTitle}>🏆 Top Selling Products</h3>
          {stats.topProducts.length > 0 ? (
            <div style={styles.list}>
              {stats.topProducts.map((product, index) => (
                <div key={index} style={styles.listItem}>
                  <div style={styles.rank}>#{index + 1}</div>
                  <div style={{ flex: 1 }}>
                    <div style={styles.itemName}>{product.name}</div>
                    <div style={styles.itemSubtext}>
                      {product.quantity} sold · ${product.revenue.toFixed(2)} revenue
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p style={styles.noData}>No sales data yet</p>
          )}
        </div>

        {/* Top Customers */}
        <div style={styles.card}>
          <h3 style={styles.cardTitle}>👑 Top Customers</h3>
          {stats.topCustomers.length > 0 ? (
            <div style={styles.list}>
              {stats.topCustomers.map((customer, index) => (
                <div key={index} style={styles.listItem}>
                  <div style={styles.rank}>#{index + 1}</div>
                  <div style={{ flex: 1 }}>
                    <div style={styles.itemName}>{customer.name}</div>
                    <div style={styles.itemSubtext}>
                      {customer.orderCount} orders · ${customer.totalSpent.toFixed(2)} spent
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p style={styles.noData}>No customer data yet</p>
          )}
        </div>
      </div>

      {/* Recent Orders */}
      <div style={styles.card}>
        <h3 style={styles.cardTitle}>📋 Recent Orders</h3>
        {stats.recentOrders.length > 0 ? (
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 1 }}>Order ID</div>
              <div style={{ flex: 1 }}>Customer</div>
              <div style={{ flex: 1 }}>Amount</div>
              <div style={{ flex: 1 }}>Status</div>
              <div style={{ flex: 1 }}>Date</div>
            </div>
            {stats.recentOrders.map(order => (
              <div key={order._id} style={styles.tableRow}>
                <div style={{ flex: 1 }}>#{order._id.slice(-8).toUpperCase()}</div>
                <div style={{ flex: 1 }}>{order.user?.name || 'N/A'}</div>
                <div style={{ flex: 1 }}>${order.totalPrice.toFixed(2)}</div>
                <div style={{ flex: 1 }}>
                  <span style={getStatusBadgeStyle(order.orderStatus)}>
                    {order.orderStatus}
                  </span>
                </div>
                <div style={{ flex: 1 }}>
                  {new Date(order.createdAt).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p style={styles.noData}>No orders yet</p>
        )}
      </div>
    </div>
  );
};

const getStatusBadgeStyle = (status) => {
  const baseStyle = {
    padding: '0.25rem 0.75rem',
    borderRadius: '9999px',
    fontSize: '0.875rem',
    fontWeight: '500'
  };

  const colors = {
    'Processing': { backgroundColor: '#fef3c7', color: '#92400e' },
    'Shipped': { backgroundColor: '#dbeafe', color: '#1e40af' },
    'Delivered': { backgroundColor: '#d1fae5', color: '#065f46' },
    'Cancelled': { backgroundColor: '#fee2e2', color: '#991b1b' }
  };

  return { ...baseStyle, ...(colors[status] || colors.Processing) };
};

